package com.assessment.finance.security; import com.assessment.finance.model.*; public class RequestContext { private static final ThreadLocal<User> CURRENT_USER=new ThreadLocal<>(); private RequestContext(){} public static void set(User user){CURRENT_USER.set(user);} public static User getRequiredUser(){ User u=CURRENT_USER.get(); if(u==null) throw new IllegalStateException("No user in context"); return u;} public static Role getRole(){ return getRequiredUser().getRole(); } public static void clear(){ CURRENT_USER.remove(); } }
